script.inlineScript:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return api.item.value.available ? 'green' : 'gray';
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  var text = api.state.translatedText;
  if(!text) return '';
	return api.item.value.available ? text.available : text.notAvailable;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    var s = api.item.value.text;
    if(!s) 
        return s;
    for (var i = Math.min(s.length - 1, 500); i < s.length && s[i] != '.'; i++);
    return api.item.value.minimizedText ? s.substring(0, i + 1) : s;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        event: 'WN documentation views',
        value: {
            ContentId: api.item.value.contentId
        }
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    var s = api.item.value.text;
    if(!api.item.value.documentation) 
        return true;
    for (var i = Math.min(s.length, 500); i < s.length && s[i] != '.'; i++);
    if (i == s.length) return false;
    return api.item.value.minimizedText;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    return {
        event: 'WN see more content',
        value: {
            ContentId: api.item.value.contentId
        }
    };
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  if(!api.item.value.text) return true;
	return api.item.value.text.length < 500;
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return "javascript:void(0);";
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  var text = api.state.translatedText;
  if(!text) return '';
	return api.item.value.minimizedText ? text.seeMore : text.seeLess;
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  var arr = api.item.value.imageArr;
	return !(arr && arr.length);
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	var contentIdx = event.context.item.index;
	var repeaterArr = api.state.repeaterArr;
	return {
		event: 'WN navigate carousel',
		value: {
			ContentId: repeaterArr[contentIdx].contentId
		}
	};
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return api.item.value.type === 'video';
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return api.item.value.type === 'image';
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return api.item.value.imageArr.length === 1;
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		event: 'WN expand carousel',
		value: {
			ContentId: api.item.value.contentId
		}
	};
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
	return api.item.value.imageArr.length > 1;
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		event: 'WN expand carousel',
		value: {
			ContentId: api.item.value.contentId
		}
	};
}

